CREATE OR REPLACE FUNCTION notify_hl7_patient_document_primary()
  RETURNS TRIGGER AS $function$
BEGIN

    -- only when new record is primary
    IF NEW.is_primary = TRUE THEN

      INSERT INTO ${hl7.integrationSchema}.hl7_event (
id,
event_type,
object_key,
event_datetime
)
VALUES (
gen_random_uuid()::varchar,
'${hl7.events.patientDocumentCreated}',
NEW.id::varchar,
NOW()
);

END IF;

RETURN NEW;
END;
$function$ LANGUAGE plpgsql;


DROP TRIGGER IF EXISTS trg_hl7_patient_document_primary ON patient_documents;

CREATE TRIGGER trg_hl7_patient_document_primary
  AFTER INSERT ON patient_documents
  FOR EACH ROW
  EXECUTE FUNCTION notify_hl7_patient_document_primary();
